swer":true},{"id":"01a218eb-54f8-7e53-a5aa-e0dd766a1e2a","description":"Happiness","correct_answer":false},{"id":"01a218eb-54f8-7d0d-bfc0-90f0bbd08d61","description":"Sadness","correct_answer":false},{"id":"01a218eb-54f8-76f8-a4d4-1d86cbad42e2","description":"Fear","correct_answer":false}]},{"id":"01a218eb-54f8-74fc-a2dd-857aa0ffb499","locale":"en-US","category":"01a21312-b489-7095-8a30-44480fe2c4f5","question":"What is the result of the mathematical operation obtained by subtracting the number of Snow White\'s dwarfs from the original title number of \'Disney Dalmatians\'?","difficulty":3,"explanation":"One Hundred and One Dalmatians gives 101; subtracting Snow White\'s seven dwarfs leaves 94.","alternatives":[{"id":"01a218eb-54f8-71c6-9a93-43f8df843040","description":"94","correct_answer":true},{"id":"01a218eb-54f8-75b3-965c-a816ca025ece","description":"97","correct_answer":false},{"id":"01a218eb-54f8-7374-bbb6-0ba2f75d98a6","description":"89","correct_answer":false},{"id":"01a218eb-54f8-788b-8519-14b9761c6a64","description":"91","correct_answer":false}]},{"id":"01a218eb-54f8-7bd0-b841-8973ebe6ecaa","locale":"en-US","category":"01a21312-b489-7095-8a30-44480fe2c4f5","question":"What type of structures are used to conduct a water stream across a valley?","difficulty":3,"explanation":"Aqueducts often relied on gravity to move water, and their elevated arches let channels cross valleys without following the terrain.","alternatives":[{"id":"01a218eb-54f8-723b-b32f-c31a7fb35fdc","description":"Aqueducts","correct_answer":true},{"id":"01a218eb-54f8-7656-9df5-3674cafc691d","description":"Canals","correct_answer":false},{"id":"01a218eb-54f8-7582-9910-8a46f6aaf12b","description":"Pipelines","correct_answer":false},{"id":"01a218eb-54f8-738a-acdb-b91e6d0c9f0f","description":"Trenches","correct_answer":false}]},{"id":"01a218eb-54f8-76d5-bd48-52a95063434a","locale":"en-US","category":"01a21312-b489-7095-8a30-44480fe2c4f5","question":"What is the Latin term for \"the arm\"?","difficulty":3,"explanation":"Bracchium is the source of the anatomical adjective brachial, as in the brachial artery.","alternatives":[{"id":"01a218eb-54f8-7662-a7ff-2ceedccb4e4b","description":"Bracchium","correct_answer":true},{"id":"01a218eb-54f8-72f0-bb3c-6ad441f19612","description":"Caput","correct_answer":false},{"id":"01a218eb-54f8-753d-9f62-81b8973d8321","description":"Pedis","correct_answer":false},{"id":"01a218eb-54f8-718b-8706-adf97b9f1c0d","description":"Oculus","correct_answer":false}]},{"id":"01a218eb-54f8-7bf0-9505-b0a31c4419ff","locale":"en-US","category":"01a21312-b489-7095-8a30-44480fe2c4f5","question":"What is the troy system of weights used to measure?","difficulty":3,"explanation":"The troy system is used to measure precious metals. A troy ounce is about 31.1 grams, compared with about 28.35 grams for the everyday avoirdupois ounce.","alternatives":[{"id":"01a218eb-54f8-7c5f-9e51-1148d6c1b4fc","description":"Precious metals","correct_answer":true},{"id":"01a218eb-54f8-76f8-941e-9bd8fd734521","description":"Radiation","correct_answer":false},{"id":"01a218eb-54f8-76c3-ae13-89b1feed5968","description":"Grain harvests","correct_answer":false},{"id":"01a218eb-54f8-7472-b7fb-56e1dde511f4","description":"Liquid fuels","correct_answer":false}]},{"id":"01a218eb-54f8-77e7-9587-f335efb0205b","locale":"en-US","category":"01a21312-b489-7095-8a30-44480fe2c4f5","question":"In January 2018, which retail chain that kids love announced it would close about 180 stores?","difficulty":3,"explanation":"Toys \"R\" Us announced the closures as part of a restructuring after filing for bankruptcy in 2017.","alternatives":[{"id":"01a218eb-54f8-7ddf-aec4-4529f7bd60a5","description":"Toys \"R\" Us","correct_answer":true},{"id":"01a218eb-54f8-7ca4-98ff-fd0a07d9265f","description":"Target","correct_answer":false},{"id":"01a218eb-54f8-7b1f-aa33-cc8df562f26c","description":"Walmart","correct_answer":false},{"id":"01a218eb-54f8-7c9e-9adf-603d4d31df88","description":"Amazon","corre